DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[PurchaseOrderHeader]([PurchaseOrderID],[RevisionNumber],[Status],[EmployeeID],[VendorID],[ShipMethodID],[OrderDate],[ShipDate],[SubTotal],[TaxAmt],[Freight],[TotalDue],[ModifiedDate],LoadBatchID) SELECT S.[PurchaseOrderID],S.[RevisionNumber],S.[Status],S.[EmployeeID],S.[VendorID],S.[ShipMethodID],S.[OrderDate],S.[ShipDate],S.[SubTotal],S.[TaxAmt],S.[Freight],S.[TotalDue],S.[ModifiedDate],@B FROM ssis_flow.Delta_PurchaseOrderHeader S;
INSERT stg.[PurchaseOrderHeader]([PurchaseOrderID],[RevisionNumber],[Status],[EmployeeID],[VendorID],[ShipMethodID],[OrderDate],[ShipDate],[SubTotal],[TaxAmt],[Freight],[TotalDue],[ModifiedDate],LoadBatchID) SELECT [PurchaseOrderID],[RevisionNumber],[Status],[EmployeeID],[VendorID],[ShipMethodID],[OrderDate],[ShipDate],[SubTotal],[TaxAmt],[Freight],[TotalDue],[ModifiedDate],@B FROM etl_raw.[PurchaseOrderHeader];
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.PurchaseOrderHeader','I',@Next,(SELECT R.[PurchaseOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[PurchaseOrderHeader] R;
END ELSE BEGIN
SELECT [PurchaseOrderID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_PurchaseOrderHeader FROM ssis_flow.Delta_PurchaseOrderHeader;
INSERT etl_v2.SourceChange SELECT @B,N'Purchasing.PurchaseOrderHeader',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[PurchaseOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_PurchaseOrderHeader C LEFT JOIN etl_raw.[PurchaseOrderHeader] R ON R.[PurchaseOrderID]=C.[PurchaseOrderID];
DELETE R FROM etl_raw.[PurchaseOrderHeader] R JOIN #CT_PurchaseOrderHeader C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[RevisionNumber]=S.[RevisionNumber],R.[Status]=S.[Status],R.[EmployeeID]=S.[EmployeeID],R.[VendorID]=S.[VendorID],R.[ShipMethodID]=S.[ShipMethodID],R.[OrderDate]=S.[OrderDate],R.[ShipDate]=S.[ShipDate],R.[SubTotal]=S.[SubTotal],R.[TaxAmt]=S.[TaxAmt],R.[Freight]=S.[Freight],R.[TotalDue]=S.[TotalDue],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[PurchaseOrderHeader] R JOIN #CT_PurchaseOrderHeader C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] JOIN ssis_flow.Delta_PurchaseOrderHeader S ON S.[PurchaseOrderID]=C.[PurchaseOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[PurchaseOrderHeader]([PurchaseOrderID],[RevisionNumber],[Status],[EmployeeID],[VendorID],[ShipMethodID],[OrderDate],[ShipDate],[SubTotal],[TaxAmt],[Freight],[TotalDue],[ModifiedDate],LoadBatchID) SELECT S.[PurchaseOrderID],S.[RevisionNumber],S.[Status],S.[EmployeeID],S.[VendorID],S.[ShipMethodID],S.[OrderDate],S.[ShipDate],S.[SubTotal],S.[TaxAmt],S.[Freight],S.[TotalDue],S.[ModifiedDate],@B FROM #CT_PurchaseOrderHeader C JOIN ssis_flow.Delta_PurchaseOrderHeader S ON S.[PurchaseOrderID]=C.[PurchaseOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[PurchaseOrderHeader] R WHERE R.[PurchaseOrderID]=S.[PurchaseOrderID]);
INSERT stg.[PurchaseOrderHeader]([PurchaseOrderID],[RevisionNumber],[Status],[EmployeeID],[VendorID],[ShipMethodID],[OrderDate],[ShipDate],[SubTotal],[TaxAmt],[Freight],[TotalDue],[ModifiedDate],LoadBatchID) SELECT R.[PurchaseOrderID],R.[RevisionNumber],R.[Status],R.[EmployeeID],R.[VendorID],R.[ShipMethodID],R.[OrderDate],R.[ShipDate],R.[SubTotal],R.[TaxAmt],R.[Freight],R.[TotalDue],R.[ModifiedDate],@B FROM etl_raw.[PurchaseOrderHeader] R JOIN #CT_PurchaseOrderHeader C ON R.[PurchaseOrderID]=C.[PurchaseOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;